/**
 * Generated by `php artisan menu:pages` (host entry: `modules:pages`) from
 * the engine registry's frontendPages() (config/tg_modules.php).
 *
 * Do not edit by hand: keys are rewritten to the canonical "./pages/<name>.tsx"
 * shape so resolvePageComponent matches uniformly across platform and module
 * pages. Re-run `php artisan modules:pages` after changing the registry.
 */
const loaders = {
        ...import.meta.glob('../../misc/BAGArt/telegram-platform-menu/resources/js/pages/**/*.tsx'),
        ...import.meta.glob('../../misc/BAGArt/tgbot-module-antispam/resources/js/pages/**/*.tsx'),
        ...import.meta.glob('../../misc/BAGArt/tgbot-module-proxy/resources/js/pages/**/*.tsx'),
};

export const modulePageLoaders = Object.fromEntries(
    Object.entries(loaders).map(([path, loader]) => [
        path.replace(/^.*\/resources\/js\/pages\//, './pages/'),
        loader,
    ]),
);
